// Résolution du lien : la page est stable, le nom du PDF change chaque année
// (CCFA-2025-FR-WEB-2.pdf). Même principe que FH et CP. `URL` n'existe pas
// dans le bac à sable (constat du 30.08) : résolution à la main.
// ÉDITIONS D'ARCHIVE (ajout du 31.08.2026) : la tendance exige plusieurs
// points, donc plusieurs ÉDITIONS — le site archive tout depuis 2014
// (ccfa.fr/analyse-statistiques/). Quand le document en file pointe
// DIRECTEMENT un PDF, cette URL fait foi ; la résolution depuis la page
// d'accueil ne vaut que pour l'édition courante. Chaque année figure dans
// deux éditions : le recouvrement rend les révisions du producteur
// visibles — c'est l'écart entre runs qui fait la tendance.
const docSource = String($('Lire le document à traiter').first().json.source_doc || '');
if (/\.pdf(\?|$)/i.test(docSource)) {
  return [{ json: { url_resolue: docSource, millesime: 'declare_par_le_document', candidats: 1 } }];
}
const page = $json.data ?? $json.body ?? '';
const liens = [...String(page).matchAll(/href="([^"]*CCFA[^"]*FR[^"]*\.pdf)"/gi)].map(m => m[1]);
if (!liens.length) throw new Error("Aucun PDF CCFA (FR) trouvé sur la page — structure modifiée, incident à instruire.");
const avecMillesime = liens.map(u => ({ u, an: Math.max(0, ...[...u.matchAll(/20(\d{2})/g)].map(m => 2000 + Number(m[1]))) }));
avecMillesime.sort((a, b) => b.an - a.an);
let url = avecMillesime[0].u.replace(/&amp;/g, '&');
if (url.startsWith('//')) url = 'https:' + url;
else if (url.startsWith('/')) url = 'https://ccfa.fr' + url;
else if (!/^https?:/i.test(url)) url = 'https://ccfa.fr/' + url;
return [{ json: { url_resolue: url, millesime: String(avecMillesime[0].an), candidats: liens.length } }];

// DÉCOUPE PAR ANCRES : la réponse à « comment ne pas ingérer tout le PDF ».
//
// Le document fait 102 pages ; Anthropic et OpenAI plafonnent vers 100 pages
// et rien ne justifie de payer 102 pages pour un tableau qui en occupe deux.
// Le texte est déjà extrait (nœud « Lire le PDF ») ; on découpe la section
// statistique par SENTINELLES DE CONTENU, jamais par numéro de page — le
// même principe que la résolution de lien (FH, CP) : on déclare ce qu'on
// cherche, pas où il se trouve, pour survivre aux rééditions.
//
// Vérifié le 31.08.2026 sur l'édition 2025 : les lignes du tableau sortent
// intactes et dans l'ordre (« Allemagne*4 1094 069-1,0 82 »), colonnes
// concaténées — ambigu pour du code, lisible par un modèle. C'est le motif
// mesuré de la voie IA sur ce document (décision de l'étudiant, tracée).
const t = String($input.first().json.text || '');
if (t.length < 5000) {
  throw new Error("Texte extrait anormalement court (" + t.length + " caractères) — lecture PDF à instruire.");
}
// DEUX CORRECTIONS MESURÉES (runs du 31.08) :
// v1 — sentinelles sur noms seuls : elles se calaient sur la PROSE des faits
// marquants, tranche sans tableau, liste vide unanime des trois modèles.
// v2 — grappe la plus dense de motifs pays+chiffre : elle atterrissait dans
// les ANNEXES de fin d'annuaire (tableaux de tonnage, plus denses encore).
// v3, retenue : le tableau visé est identifié par un APPARIEMENT — la ligne
// d'agrégat « EUROPE » suivie de chiffres LA PLUS PROCHE APRÈS un titre
// « PRODUCTION MONDIALE DE V » (moins de 6 000 caractères d'écart). Vérifié
// sur les trois éditions : tranche de ~5 100 caractères portant l'en-tête
// des années, les ~25 pays et la ligne TOTAL.
const titres = [];
let i = -1;
while ((i = t.indexOf('PRODUCTION MONDIALE DE V', i + 1)) >= 0) titres.push(i);
const europes = [...t.matchAll(/EUROPE\s*\n\s*\d/g)].map(m => m.index);
let choix = null;
for (const ti of titres) for (const e of europes) {
  const ecart = e - ti;
  if (ecart > 0 && ecart < 6000 && (!choix || ecart < choix.ecart)) choix = { e, ecart };
}
if (!choix) {
  throw new Error("Aucune ligne EUROPE chiffrée à moins de 6000 caractères d'un titre PRODUCTION MONDIALE (" + titres.length + " titres, " + europes.length + " lignes EUROPE) — structure du document modifiée, incident à instruire.");
}
const debut = Math.max(0, choix.e - 600);
const fin = Math.min(t.length, choix.e + 4500);
const tranche = t.slice(debut, fin);
if (!/Allemagne[*)]?\s?\d/.test(tranche) || !/Chine\s?\d/.test(tranche)) {
  throw new Error("La tranche découpée ne contient pas les lignes attendues (Allemagne, Chine) — découpe à instruire, rien n'est envoyé aux modèles.");
}
return [{ json: {
  tranche,
  longueur_document: t.length,
  longueur_tranche: tranche.length,
  part_ingeree_pct: Math.round(1000 * tranche.length / t.length) / 10
} }];

// La charge : la TRANCHE seulement, jamais le document entier.
const prep = $('Découper la section statistique').first().json;
const anneeDoc = Number($('Lire le document à traiter').first().json.period) || new Date().getFullYear() - 1;
const consigne = `Tu es un extracteur de données. Le texte fourni est extrait du tableau « LA PRODUCTION MONDIALE DE VÉHICULES » de l'annuaire CCFA (production automobile par pays, en MILLIERS de véhicules, colonnes : valeur année précédente, valeur dernière année, variation %, base 100 = 2019). Les colonnes sont concaténées sans séparateur : sers-toi de la variation (signée, avec virgule) et de la base (entier final) pour délimiter.

Extrais UNIQUEMENT les lignes de PAYS (jamais les agrégats EUROPE, AMÉRIQUE, ASIE-OCÉANIE, ACEUM, ASEAN, PECO, « Europe occidentale », « Europe centrale et orientale », « Amérique du Sud », AFRIQUE), PLUS la ligne TOTAL du tableau, rendue avec {"pays": "TOTAL", "iso3": "WLD"} — c'est la seule ligne d'agrégat admise.

Renvoie STRICTEMENT un objet JSON valide, sans texte autour et sans balises de code :
{"annee_recente": "${anneeDoc}", "annee_precedente": "${anneeDoc - 1}", "lignes": [{"pays": "Allemagne", "iso3": "DEU", "v_precedente": 1234, "v_recente": 1234}, ...]}

Règles impératives :
- Une entrée par pays, dans l'ordre du tableau. Valeurs en milliers TELLES QU'IMPRIMÉES, sans recalcul.
- iso3 : code ISO 3166-1 alpha-3 du pays.
- Si une valeur est illisible, mets null. N'utilise AUCUNE source autre que le texte fourni.
- Les années : lis-les dans l'en-tête du tableau, ne les suppose pas.`;
return [{ json: {
  tranche: prep.tranche,
  consigne,
  part_ingeree_pct: prep.part_ingeree_pct,
  run_id: $('Ouvrir le run').first().json.run_id,
  source_doc: $('Extraire le lien du PDF').first().json.url_resolue
} }];

