// CONSENSUS PAR PAYS, CONTRÔLE PAR LA SOURCE PRIMAIRE.
//
// Doctrine (cascade § 10.4) : vérité terrain d'abord, consensus ensuite,
// humain enfin. Cas exceptionnel et précieux : la source primaire (OICA)
// publie la vérité en JSON lisible dans sa page (attributs data-data,
// classements top-10 par année). Chaque valeur extraite par les modèles
// est donc confrontée à l'OICA quand le pays y figure :
//   - concordance (±0,1 %, arrondi au millier) : contrôle de rang 1 SATISFAIT ;
//   - discordance : incident, la valeur va en file quelle que soit l'unanimité ;
//   - pays hors top-10 OICA : non vérifiable — le consensus seul décide,
//     comme pour la CP hors contrôle arithmétique, et la note le dit.
function texte(x) {
  if (Array.isArray(x.output)) return x.output.flatMap(i => i.content || []).filter(p => p.type === 'output_text' || p.type === 'text').map(p => p.text).join('');
  if (Array.isArray(x.content)) return x.content.filter(b => b.type === 'text').map(b => b.text).join('');
  if (Array.isArray(x.candidates)) return ((x.candidates[0] || {}).content?.parts || []).filter(p => p.text).map(p => p.text).join('');
  return '';
}
function parser(t) {
  const net = String(t).replace(/^```json/i, '').replace(/^```/, '').replace(/```$/, '').trim();
  return JSON.parse(net);
}
function modale(vals) {
  const comptes = new Map();
  for (const v of vals) if (v !== null && v !== undefined) comptes.set(v, (comptes.get(v) || 0) + 1);
  if (!comptes.size) return { valeur: null, part: 0 };
  const tri = [...comptes.entries()].sort((a, b) => b[1] - a[1]);
  if (tri.length > 1 && tri[0][1] === tri[1][1]) return { valeur: null, part: tri[0][1] / vals.length };
  return { valeur: tri[0][0], part: tri[0][1] / vals.length };
}

// --- lectures des trois modèles ---
const lectures = []; const incidentsModele = [];
const noms = ['openai', 'anthropic', 'google'];
$input.all().forEach((item, i) => {
  try {
    const d = parser(texte(item.json));
    if (!Array.isArray(d.lignes)) throw new Error('pas de champ lignes');
    lectures.push({ nom: noms[i] || ('modele_' + i), d });
  } catch (e) { incidentsModele.push(`${noms[i] || i} : ${String(e.message).slice(0, 80)}`); }
});
if (lectures.length < 2) throw new Error('Moins de deux lectures exploitables : ' + incidentsModele.join(' | '));

// --- vérité OICA : tous les blocs data-data de la page, pays -> totaux vus ---
const brutOica = String($('Lire la vérité OICA').first().json.data ?? '');
// CORRECTION DU 31.08 (run 181) : la v1 comparait à TOUS les blocs sans année
// et déclarait « discorde » quand l'OICA n'avait pas publié l'année demandée —
// 23 valeurs unanimes et justes routées en file pour rien. Une valeur
// introuvable n'est pas une valeur contredite. Chaque bloc de la page est
// précédé d'un titre daté (« World Motor Vehicle - Production - 2015 ») :
// le contrôle est désormais PAR ANNÉE, et seuls les blocs « World Motor
// Vehicle - Production » (totaux) font foi — jamais les blocs par type.
const oica = {};
{
  const morceaux = [...brutOica.matchAll(/World Motor Vehicle - Production - (\d{4})|data-data="([^"]+)"/g)];
  let anneeCourante = null;
  for (const m of morceaux) {
    if (m[1]) { anneeCourante = m[1]; continue; }
    if (!anneeCourante) continue;
    try {
      const rows = JSON.parse(m[2].replace(/&quot;/g, '"').replace(/&amp;/g, '&'));
      for (const r of rows.slice(1)) {
        const nom = String(r[0]).toUpperCase().trim();
        const tot = (Number(r[1]) > 0 ? Number(r[1]) : 0) + (Number(r[2]) > 0 ? Number(r[2]) : 0);
        if (tot > 0) ((oica[anneeCourante] = oica[anneeCourante] || {})[nom] = tot);
      }
    } catch (e) { /* bloc illisible : ignoré */ }
    anneeCourante = null;  // un titre ne vaut que pour le bloc qui le suit
  }
}
const ISO_VERS_OICA = { CHN:'CHINA', JPN:'JAPAN', IND:'INDIA', DEU:'GERMANY', KOR:'SOUTH KOREA',
  ESP:'SPAIN', BRA:'BRAZIL', CZE:'CZECHIA', USA:'USA', IDN:'INDONESIA', FRA:'FRANCE', MEX:'MEXICO',
  CAN:'CANADA', TUR:'TURKEY', RUS:'RUSSIA', GBR:'UK', ITA:'ITALY', SVK:'SLOVAKIA', THA:'THAILAND', MYS:'MALAYSIA' };
function controleOica(iso3, annee, valeurMilliers) {
  const nom = ISO_VERS_OICA[iso3];
  const parAnnee = oica[String(annee)];
  if (!nom || !parAnnee || !(nom in parAnnee)) return 'non_verifiable';
  const cible = valeurMilliers * 1000, tol = Math.max(1000, cible * 0.001);
  return Math.abs(parAnnee[nom] - cible) <= tol ? 'concorde' : 'discorde';
}

// --- consensus par pays et par année ---
const seuilsBruts = $('Lire les seuils de consensus').first().json.seuils || {};
const s = Number(seuilsBruts['A1']); const seuil = Number.isFinite(s) && s > 0 ? s : 1;
const doc = $('Lire le document à traiter').first().json;
const charge = $('Préparer la charge').first().json;
const anRecent = modale(lectures.map(l => l.d.annee_recente)).valeur;
const anPrec = modale(lectures.map(l => l.d.annee_precedente)).valeur;

const parIso = {};
for (const l of lectures) for (const r of (l.d.lignes || [])) {
  const iso = String(r.iso3 || '').toUpperCase();
  if (!/^[A-Z]{3}$/.test(iso)) continue;
  (parIso[iso] = parIso[iso] || {}).__pays = r.pays;
  (parIso[iso][l.nom] = parIso[iso][l.nom] || {}).vr = r.v_recente;
  parIso[iso][l.nom].vp = r.v_precedente;
}
const sorties = [];
for (const [iso, obj] of Object.entries(parIso)) {
  for (const [annee, champ] of [[anRecent, 'vr'], [anPrec, 'vp']]) {
    if (!annee) continue;
    const vals = lectures.map(l => obj[l.nom] ? obj[l.nom][champ] : undefined).map(v => v === undefined ? null : v);
    const { valeur, part } = modale(vals);
    const incidents = [...incidentsModele];
    let ctrl = 'non_verifiable';
    if (valeur !== null) {
      ctrl = controleOica(iso, annee, valeur);
      if (ctrl === 'discorde') incidents.push(`controle OICA : ${iso} ${annee} = ${valeur} milliers introuvable dans les donnees publiees OICA`);
    }
    if (part < seuil) incidents.push(`consensus ${Math.round(part * 100)} % sous le seuil declare de ${Math.round(seuil * 100)} %`);
    sorties.push({ json: {
      // la ligne TOTAL du tableau est portée par la zone World — la
      // convention des indicateurs mondiaux de la grille (A3, A11).
      indicator_id: 'A1', run_id: charge.run_id, period: String(annee), geo: iso === 'WLD' ? 'World' : iso,
      value: valeur !== null ? valeur * 1000 : null,   // milliers -> unités (unité du référentiel)
      consensus_score: Number(part.toFixed(4)), seuil_applique: seuil,
      controle_oica: ctrl, source_doc: charge.source_doc, doc_id: doc.doc_id,
      diffusable: valeur !== null && part >= seuil && ctrl !== 'discorde',
      extractions: JSON.stringify({ pays: obj.__pays, valeurs_par_modele: Object.fromEntries(lectures.map(l => [l.nom, obj[l.nom] ? obj[l.nom][champ] : null])), controle_oica: ctrl, part, incidents }),
      incidents
    } });
  }
}
if (!sorties.length) throw new Error('Aucune ligne pays extraite par consensus.');
return sorties;
